243:static inline int32_t le_to_i32(const uint8_t *buf) {
static inline int32_t le_to_i32(const uint8_t *buf) {
    uint32_t v = le_to_u32(buf);
    return v < 0x80000000U ? (int32_t) v : -((int32_t) (0xffffffffU - v)) - 1;
}
